s=s.replace('3.7 if enemy.kind=="boss" else 2.1','3.7 if enemy.boss() else 2.1').replace('"落锤！" if enemy.kind=="boss" else "!"','enemy.pattern+"！"')
s=s.replace('"序章 · 断电之夜     /     v0.1 可玩原型"','"灰闸囚厂 × 锈脊齿轮井   /   18 房间 · v0.4.0"')
s=s.replace('"凯恩 · 匕首" if game.active_slot==0 else "洛铆 · 机械重击"','["凯恩 · 匕首","洛铆 · 机械重击","伊瑟 · 弓箭"][game.active_slot]')
