s=s.replace('\t\tif game.room==10:\n\t\t\ttext_at(Vector2(w/2-160,200),"水位 %.1f / 2  ·  %s"%[game.water[2],"旁路开放" if game.water[3] else "蒸汽隔离"],18,GOLD)','\t\tvar alive:=0\n\t\tfor enemy in game.enemies:\n\t\t\tif is_instance_valid(enemy) and enemy.hp>0:alive+=1\n\t\ttext_at(Vector2(w-368,153),"本室敌人 %d   /   Tab 查看完整路线"%alive,16,GOLD)')
s=s.replace('for i in range(2):','for i in range(3):').replace('["裂影刺","齿刃旋舞"] if game.active_slot==0 else ["铜核修补击","齿轮过载"]','[["裂影刺","齿刃旋舞","裂影空冲"],["铜核修补击","齿轮过载","机械推进"],["穿甲射击","裂界强弓","游侠空冲"]][game.active_slot]')
s=s.replace('w*.18+i*350,h*.44','w*.12+i*w*.27,h*.44').replace('game.learn_skill.bind(i),320','game.learn_skill.bind(i),w*.25')
